  out.append('<div class="table"><table>'+''.join('<tr>'+''.join(('<th>' if i==0 else '<td>')+inline(v)+('</th>' if i==0 else '</td>') for v in row)+'</tr>' for i,row in enumerate(table))+'</table></div>');table=[]
